# =============================================================================
# 05b_generate_cluster_labels.R
# -----------------------------------------------------------------------------
# Cluster labelling, step 2: one descriptive English label (max 250 characters)
# per cluster-year, generated by gpt-4.1-mini (temperature 0.3) from the
# sampled texts, each truncated to 300 characters.
#
# Resumable: each label is appended to the CSV as soon as it is generated, and
# cluster-years already in the file are skipped. Retries with increasing waits
# (up to 5 attempts).
#
# Input : output/cluster_samples.rds   (from 05a)
# Output: output/cluster_labels.csv    (year, cluster, label, n_urls)
# Needs : OPENAI_API_KEY environment variable
# =============================================================================

library(httr2)
library(jsonlite)

SAMPLES_FILE <- "output/cluster_samples.rds"
OUTPUT_FILE  <- "output/cluster_labels.csv"
MODEL        <- "gpt-4.1-mini"
MAX_CHARS    <- 300
MAX_RETRIES  <- 5
RETRY_WAIT   <- 10

api_key <- Sys.getenv("OPENAI_API_KEY")
if (api_key == "") stop("Set the OPENAI_API_KEY environment variable")

samples <- readRDS(SAMPLES_FILE)
groups  <- unique(samples[, c("year", "cluster", "n_urls")])

existing <- if (file.exists(OUTPUT_FILE)) {
  read.csv(OUTPUT_FILE, stringsAsFactors = FALSE)
} else {
  data.frame(year = integer(), cluster = integer(), label = character(), n_urls = integer())
}

build_prompt <- function(texts) {
  numbered <- paste(seq_along(texts), substr(texts, 1, MAX_CHARS), sep = ". ")
  list(
    list(role = "system", content = paste(
      "You are a research assistant helping label clusters of Brazilian political",
      "web content. Given a set of representative text snippets from URLs in a",
      "cluster, provide a concise English label (max 250 characters) that",
      "describes the common theme or topic. Return ONLY the label, nothing else."
    )),
    list(role = "user", content = paste0(
      "Here are representative text snippets from a cluster of Brazilian ",
      "political URLs. What is the common theme?\n\n", paste(numbered, collapse = "\n")
    ))
  )
}

call_openai <- function(messages) {
  for (attempt in seq_len(MAX_RETRIES)) {
    result <- tryCatch({
      resp <- request("https://api.openai.com/v1/chat/completions") |>
        req_headers("Authorization" = paste("Bearer", api_key),
                    "Content-Type" = "application/json") |>
        req_body_json(list(model = MODEL, messages = messages,
                           temperature = 0.3, max_tokens = 100)) |>
        req_timeout(60) |>
        req_perform()
      trimws(resp_body_json(resp)$choices[[1]]$message$content)
    }, error = function(e) {
      if (attempt == MAX_RETRIES) stop(conditionMessage(e))
      Sys.sleep(RETRY_WAIT * attempt)
      NULL
    })
    if (!is.null(result)) return(result)
  }
}

for (i in seq_len(nrow(groups))) {
  yr <- groups$year[i]; cl <- groups$cluster[i]; nu <- groups$n_urls[i]
  if (any(existing$year == yr & existing$cluster == cl)) next

  texts <- samples$alltext[samples$year == yr & samples$cluster == cl]
  label <- call_openai(build_prompt(texts))
  if (nchar(label) > 250) label <- paste0(substr(label, 1, 247), "...")

  if (!file.exists(OUTPUT_FILE)) writeLines("year,cluster,label,n_urls", OUTPUT_FILE)
  cat(sprintf('%d,%d,"%s",%d\n', yr, cl, gsub('"', '""', label), nu),
      file = OUTPUT_FILE, append = TRUE)
  cat(sprintf("[%d/%d] %d-%d: %s\n", i, nrow(groups), yr, cl, label))
}
